head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil71801";
scwin.form = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil71801.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "btn_DigitalSelectSub", fn: function(){ return ((dma_page.get("total") ?? (() => { throw new Error("unresolved:" + "page.total"); })()) !== 0); } }, { id: "btn_DigitalExcelDownload", fn: function(){ return ((dma_page.get("total") ?? (() => { throw new Error("unresolved:" + "page.total"); })()) !== 0); } }, { id: "btn_DigitalExcelUploadPop", fn: function(){ return ((dma_page.get("total") ?? (() => { throw new Error("unresolved:" + "page.total"); })()) !== 0); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return "전체 " + String(dma_page.get("total")) + "건 (" + String(dma_page.get("currentPage")) + "/" + String(dma_page.get("pageCount")) + " 페이지) "; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

// [A] 초기 목록 미해결 — 자기 목록을 채우는 tx 가 3개다(tx_fn_Search, tx_fn_digitalApplDel, tx_fn_DigitalMst) — 어느 것이 «열자마자» 인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「검색」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function(e){
    try {
        await scwin.search()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil71801.btn_Search_onclick' }); }
};

/**
 * @method
 * @name slc_lastApplCnt_onchange
 * @description slc_lastApplCnt 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_lastApplCnt_onchange = async function(e){
    try {
        await scwin.search();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil71801.slc_lastApplCnt_onchange' }); }
};

/**
 * @method
 * @name grd_pageList_oncellclick
 * @description grd_pageList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_pageList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_pageList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_pageList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (r["applStatusCd"] === '00' || r["applStatusCd"] === '03') { await scwin.digitalApplDel(r["bzProcsNo"], r["applStatusCd"]); return; }
        await scwin.digitalMst(r["isuCd"], r["bzProcsNo"], r["applStatusCd"], r["lastSaveStatCd"], r["rsnTabNo"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_pageList.oncellclick' });
    }
};

/**
 * @method
 * @name btn_DigitalSelectSub_onclick
 * @description 「선택제출」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_DigitalSelectSub_onclick = function(e){
    try {
        fn_DigitalSelectSub()  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_DigitalSelectSub — 폼·DOM 의존(B-7)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil71801.btn_DigitalSelectSub_onclick' }); }
};

/**
 * @method
 * @name btn_DigitalExcelDownload_onclick
 * @description 「엑셀다운」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_DigitalExcelDownload_onclick = function(e){
    try {
        fn_DigitalExcelDownload()  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_DigitalExcelDownload — 폼·DOM 의존(B-7)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil71801.btn_DigitalExcelDownload_onclick' }); }
};

/**
 * @method
 * @name btn_DigitalExcelUploadPop_onclick
 * @description 「엑셀업로드」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_DigitalExcelUploadPop_onclick = function(e){
    try {
        fn_DigitalExcelUploadPop('' + dma_readDataVO.get("listBzCd") + '')  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_DigitalExcelUploadPop — JSP 팝업(window.open+폼 제출 — 회신)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil71801.btn_DigitalExcelUploadPop_onclick' }); }
};

/**
 * @method
 * @name __on_enter_1_ipt_isunm
 * @description on enter 1 ipt isunm 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.__on_enter_1_ipt_isunm = async function(e){
    try {
        const ev = e;
        if(($c.util.getKeyCode(ev))===13){ await scwin.search() }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil71801.__on_enter_1_ipt_isuNm' }); }
};

/**
 * @method
 * @name krxpage_pagenavigator_92_onclick
 * @description krxpage_pagenavigator_92 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_92_onclick = async function (index) {
    try {
        const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index;
        $c.util.getComponent('dma_SearchReq').set('pageIndex', pi);
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldfil71801.krxpage_pagenavigator_92_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Search
 * @description Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Search = async function () {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: "/digital/DigitalList.do",
        ref: "dma_SearchReq",
        target: "dlt_pageList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_digitalApplDel
 * @description digital Appl Del 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_digitalApplDel = async function () {
    const sbmOptions = {
        id: "tx_fn_digitalApplDel",
        method: "post",
        action: "/digital/DigitalList.do",
        ref: "dma_digitalApplDelReq",
        target: "dlt_pageList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_DigitalMst
 * @description Digital Mst 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_DigitalMst = async function () {
    const sbmOptions = {
        id: "tx_fn_DigitalMst",
        method: "post",
        action: "/digital/DigitalList.do",
        ref: "dma_DigitalMstReq",
        target: "dlt_pageList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name grd_pageList_fmt_column8
 * @description grd page List fmt column8 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_pageList_fmt_column8 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_pageList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "applStatusCd") ?? '') : '');
        if (['00','03'].indexOf(v) >= 0) { return '<a href="javascript:void(0)"' + (false ? ' class="lnk"' : '') + '>' + "삭제" + '</a>'; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_pageList.column8" }); return String(data ?? ''); }
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    scwin.form = (document.digitalListForm || { elements: [] });
    scwin.form.action = '/digital/DigitalList.do';
    $c.util.getComponent('dma_SearchReq').set('method', 'searchList');
    await scwin.tx_fn_Search();
};

/**
 * @method
 * @name digitalApplDel
 * @description digital Appl Del 처리
 * @param {*} bzProcsNo bzProcsNo
 * @param {String} applStatusCd applStatusCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.digitalApplDel = async function (bzProcsNo, applStatusCd) {
    if (applStatusCd === '02') {
        await $c.win.alert('반송인 경우 삭제할 수 없습니다.');
        return;
    }
    if (!await $c.fil.confirmJob('D')) {
        return;
    }
    scwin.form = (document.digitalListForm || { elements: [] });
    scwin.form.action = '/digital/DigitalList.do';
    $c.util.getComponent('dma_SearchReq').set('method', 'deleteList');
    $c.util.getComponent('dma_SearchReq').set('bzProcsNo', bzProcsNo);
    await scwin.tx_fn_digitalApplDel();
};

/**
 * @method
 * @name digitalMst
 * @description digital Mst 처리
 * @param {String} isuCd isuCd
 * @param {*} bzProcsNo bzProcsNo
 * @param {String} applStatusCd applStatusCd
 * @param {String} lastSaveStatCd lastSaveStatCd
 * @param {*} rsnTabNo rsnTabNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.digitalMst = async function (isuCd, bzProcsNo, applStatusCd, lastSaveStatCd, rsnTabNo) {
    scwin.form = (document.digitalListForm || { elements: [] });
    scwin.form.action = '/digital/DigitalList.do';
    $c.util.getComponent('dma_SearchReq').set('method', 'detailList');
    $c.util.getComponent('dma_SearchReq').set('isuCd', isuCd);
    $c.util.getComponent('dma_SearchReq').set('bzProcsNo', bzProcsNo);
    if (applStatusCd === '03') {
        if (rsnTabNo !== '05') {
            $c.util.getComponent('dma_SearchReq').set('lastSaveStatCd', Number(rsnTabNo));
        } else {
            $c.util.getComponent('dma_SearchReq').set('lastSaveStatCd', 0);
        }
    } else {
        $c.util.getComponent('dma_SearchReq').set('lastSaveStatCd', lastSaveStatCd);
    }
    $c.util.getComponent('dma_SearchReq').set('applStatusCd', applStatusCd);
    await scwin.tx_fn_DigitalMst();
};
